import{_ as t,o as i,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Detect, Decide, Fence Resolving Netsplits in 3 AZ Stretch Cluster","description":"","frontmatter":{"title":"Detect, Decide, Fence Resolving Netsplits in 3 AZ Stretch Cluster","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph","stretch cluster","network partition","high availability","distributed storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster.md","filePath":"posts/2026/Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster.md","lastUpdated":1780459816000}'),a={name:"posts/2026/Detect_Decide_Fence_Resolving_Netsplits_in_3_AZ_Stretch_Cluster.md"};function o(l,e,c,s,d,p){return i(),n("div",null,[...e[0]||(e[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲聚焦于 Ceph 从 2AZ（双可用区）stretch 模式扩展到 3 AZ（三可用区）部署时遇到的 split-brain 问题，以及对应的检测、决策与 fencing 解决方案。</p><h2 id="背景-从-2-az-到-3-az" tabindex="-1">背景：从 2 AZ 到 3 AZ <a class="header-anchor" href="#背景-从-2-az-到-3-az" aria-label="Permalink to &quot;背景：从 2 AZ 到 3 AZ&quot;">​</a></h2><p><strong>2 AZ stretch 模式</strong>将集群跨两个数据中心部署，将 failure domain 从 host/OSD 级别提升至 zone/数据中心级别。由于跨数据中心通信走 WAN 而非 LAN，网络分区（network partition）成为需要处理的核心问题。</p><p>2 AZ 模式通过引入 <strong>tiebreaker monitor</strong> 解决网络分区问题——tiebreaker 会自动选择连通性更好的一侧，隐式完成 net split 的解决。</p><p>随着业务对更高 availability 的需求，需要扩展到 <strong>3 AZ</strong>。目标同样是：在单个 zone 故障或网络分区时保持集群可用。然而，3 AZ 架构无法沿用 tiebreaker monitor 的设计，因此需要将同等能力内嵌到 MON 自身逻辑中。</p><h2 id="问题-3-az-下的-split-brain" tabindex="-1">问题：3 AZ 下的 Split-Brain <a class="header-anchor" href="#问题-3-az-下的-split-brain" aria-label="Permalink to &quot;问题：3 AZ 下的 Split-Brain&quot;">​</a></h2><p>以 DC1、DC2、DC3 三个数据中心为例，当 DC1 与 DC2 之间发生网络分区时：</p><ol><li>DC2 的 OSD（如 OSD 3、OSD 4）向 leader monitor 上报无法连接 DC1 的 OSD。</li><li>Leader monitor 将DC1 的 OSD 标记为 down。</li><li>但 DC1 的 OSD 0 仍能连接到 leader monitor，并请求将自己标记回 up。</li><li>Leader monitor 反复在 down/up 之间切换，导致 PG 持续 re-pering，最终读写不可用。</li></ol><p>根本原因是 monitor 在两侧都能收到消息时做出了矛盾决策，需要明确选出&quot;胜出方&quot;继续服务 IO。</p><h2 id="解决方案-detect-→-decide-→-fence" tabindex="-1">解决方案：Detect → Decide → Fence <a class="header-anchor" href="#解决方案-detect-→-decide-→-fence" aria-label="Permalink to &quot;解决方案：Detect → Decide → Fence&quot;">​</a></h2><h3 id="第一步-检测-net-split" tabindex="-1">第一步：检测 Net Split <a class="header-anchor" href="#第一步-检测-net-split" aria-label="Permalink to &quot;第一步：检测 Net Split&quot;">​</a></h3><p>Ceph MON 持续追踪各 peer 之间的连通性评分。该功能已在 <strong>Squid</strong> 版本合并，可以：</p><ul><li>在 <code>ceph -s</code> 的 health warning 中显示 monitor 级别的连通性问题（如&quot;monitor A 无法连接 monitor D&quot;）。</li><li>当 failure domain 配置为 zone/数据中心时，能够判断出 DC1 与 DC2 之间发生了完整的 net split。</li></ul><h3 id="第二步-决定胜出分区-decide" tabindex="-1">第二步：决定胜出分区（Decide） <a class="header-anchor" href="#第二步-决定胜出分区-decide" aria-label="Permalink to &quot;第二步：决定胜出分区（Decide）&quot;">​</a></h3><p>检测到 net split 后，需要从可能的分区组合中选出胜出方。以 DC1-DC2-DC3 为例，候选组合为 {DC1, DC3} 和 {DC2, DC3}。</p><p><strong>算法：Bron-Kerbosch（BK）最大团搜索</strong></p><p>将各 zone 建模为图的顶点，连通性为边，使用 BK 算法寻找<strong>最大团（maximal clique）</strong>——即每个顶点都与组内其他顶点直接相连的最大子集。由于 zone 数量在实际部署中极少，算法的指数级时间复杂度不构成问题。</p><p>在上述例子中，算法会找到两个等大的最大团：{DC1, DC3} 和 {DC2, DC3}，需要进一步决策。</p><p><strong>决策方式一：用户配置 net split zone preference</strong></p><p>用户在部署 3 AZ 前预先配置各 zone 的优先级（如 DC1 &gt; DC2 &gt; DC3），系统据此计算胜出分区。</p><p><strong>决策方式二：自动启发式（Heuristics）</strong></p><p>若用户不配置偏好，Ceph 按以下优先级依次比较，首个分出胜负的指标即决定胜出方：</p><ol><li><strong>Total effective OSD weight</strong>：OSD CRUSH weight × OSD map weight（容量），权重更高的分区胜出。</li><li><strong>Monitor 数量</strong>：MON 更多意味着 quorum 更强，集群更稳定。</li><li><strong>Monitor 连接评分总和</strong>：连通性更好的分区胜出。</li><li><strong>字典序比较</strong>：若以上全部相同，则按字典序决定，确保确定性。</li></ol><h3 id="第三步-fencing-落败分区" tabindex="-1">第三步：Fencing 落败分区 <a class="header-anchor" href="#第三步-fencing-落败分区" aria-label="Permalink to &quot;第三步：Fencing 落败分区&quot;">​</a></h3><p>确定胜出分区后，需要对落败分区执行 fencing，防止其继续操作：</p><p><strong>Fencing 前的准备：</strong></p><ul><li>将需要 fence 的 OSD 信息持久化到 OSD map。</li><li>全局设置 <code>no recovery</code>、<code>no backfill</code>，避免 fencing 过程中发生数据迁移。</li></ul><p><strong>Fencing 的具体行为：</strong></p><ul><li>MON 忽略来自被 fence OSD 的所有上报和消息，从根本上消除 split-brain 的触发条件。</li><li>被 fence 的 OSD 不再作为 PG acting set 的候选，PG 不会选择落败分区的 OSD 参与服务。</li><li>Fencing 期间禁止修改 net split zone preference，避免竞态条件。</li></ul><p><strong>Fencing 完成后：</strong></p><ul><li>解除全局 <code>no recovery</code>、<code>no backfill</code> 限制。</li><li>PG 自动进入 active 状态（处于 undersized + degraded，但集群保持可用，继续服务 IO）。</li></ul><h2 id="fence-解除-lift-fencing" tabindex="-1">Fence 解除（Lift Fencing） <a class="header-anchor" href="#fence-解除-lift-fencing" aria-label="Permalink to &quot;Fence 解除（Lift Fencing）&quot;">​</a></h2><p>为防止 fence flapping（因瞬时网络抖动导致反复 fence/unfence），引入 <strong>90 秒阈值</strong>：MON 连续 90 秒未检测到网络分区，才会解除 fence。</p><p>Fence 解除后，PG 重新进入 pering 流程，最终恢复为 active+clean 状态，集群完全恢复正常。</p><h2 id="边界情况处理" tabindex="-1">边界情况处理 <a class="header-anchor" href="#边界情况处理" aria-label="Permalink to &quot;边界情况处理&quot;">​</a></h2><p><strong>场景三（不切换胜出方）：</strong> 当 fencing 已在进行中，启发式计算发现落败分区的连通性评分反而更高时，系统<strong>不会</strong>切换胜出方。原因是切换代价远大于收益——切换会中断当前正在进行的操作，引入不确定性。因此保持当前选择，以次优状态继续服务 IO。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>机制</th><th>版本</th></tr></thead><tbody><tr><td>检测 net split</td><td>MON 连通性评分 + BK 算法</td><td>Squid（已合并）</td></tr><tr><td>决定胜出分区</td><td>用户偏好 或 四级启发式</td><td>开发中</td></tr><tr><td>Fencing 落败分区</td><td>OSD map 持久化 + MON 忽略消息</td><td>开发中</td></tr><tr><td>解除 Fence</td><td>90 秒无分区阈值</td><td>开发中</td></tr></tbody></table><p>该方案将 2 AZ tiebreaker monitor 的核心思想内嵌到 MON 自身，使 3 AZ stretch cluster 在无外部仲裁节点的情况下，也能自动检测、决策并隔离网络分区，保障集群持续提供 IO 服务。</p>',40)])])}const D=t(a,[["render",o]]);export{g as __pageData,D as default};
